package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {

    @Test
    public void testIsNumber_NullAndEmpty() {
        assertFalse("Null should return false", NumberUtils.isNumber(null));
        assertFalse("Empty string should return false", NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue("Simple integer", NumberUtils.isNumber("123"));
        assertTrue("Negative integer", NumberUtils.isNumber("-123"));
        assertTrue("Zero", NumberUtils.isNumber("0"));
        assertTrue("Large integer", NumberUtils.isNumber("9223372036854775807"));
        assertFalse("Just a sign", NumberUtils.isNumber("-"));
        assertFalse("Just a plus", NumberUtils.isNumber("+"));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Hex lowercase", NumberUtils.isNumber("0x123"));
        assertTrue("Hex uppercase", NumberUtils.isNumber("0xABC"));
        assertTrue("Hex mixed", NumberUtils.isNumber("0x1aF"));
        assertFalse("Incomplete hex", NumberUtils.isNumber("0x"));
        assertFalse("Invalid hex char", NumberUtils.isNumber("0xG12"));
        assertTrue("Negative hex", NumberUtils.isNumber("-0x123"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Simple decimal", NumberUtils.isNumber("123.45"));
        assertTrue("Decimal with sign", NumberUtils.isNumber("-123.45"));
        assertTrue("Trailing decimal point", NumberUtils.isNumber("123."));
        assertTrue("Decimal starting with dot", NumberUtils.isNumber(".123"));
        assertFalse("Multiple decimal points", NumberUtils.isNumber("1.2.3"));
        assertFalse("Just a dot", NumberUtils.isNumber("."));
    }

    @Test
    public void testIsNumber_Exponents() {
        assertTrue("Scientific notation", NumberUtils.isNumber("123e45"));
        assertTrue("Scientific notation upper", NumberUtils.isNumber("123E45"));
        assertTrue("Scientific with sign", NumberUtils.isNumber("123e+45"));
        assertTrue("Scientific with negative sign", NumberUtils.isNumber("123e-45"));
        assertTrue("Scientific with decimal", NumberUtils.isNumber("1.23e45"));
        assertFalse("E without digits before", NumberUtils.isNumber("e123"));
        assertFalse("E without digits after", NumberUtils.isNumber("123e"));
        assertFalse("E with sign but no digits after", NumberUtils.isNumber("123e+"));
        assertFalse("Multiple Es", NumberUtils.isNumber("123e45e67"));
        assertFalse("Decimal in exponent", NumberUtils.isNumber("123e4.5"));
    }

    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F (Allowed after digits/decimal, not after exponent)
        assertTrue("Float suffix f", NumberUtils.isNumber("123f"));
        assertTrue("Float suffix F", NumberUtils.isNumber("123F"));
        assertTrue("Double suffix d", NumberUtils.isNumber("123d"));
        assertTrue("Double suffix D", NumberUtils.isNumber("123D"));
        assertTrue("Decimal with f", NumberUtils.isNumber("123.45f"));
        assertFalse("Suffix after exponent", NumberUtils.isNumber("123e4f"));

        // l, L (Allowed only if no exponent and no decimal point)
        assertTrue("Long suffix l", NumberUtils.isNumber("123l"));
        assertTrue("Long suffix L", NumberUtils.isNumber("123L"));
        assertFalse("Long with decimal", NumberUtils.isNumber("123.4l"));
        assertFalse("Long with exponent", NumberUtils.isNumber("123e4l"));
    }

    @Test
    public void testIsNumber_EdgeCases() {
        assertFalse("Alpha characters", NumberUtils.isNumber("abc"));
        assertFalse("Mixed alpha numeric", NumberUtils.isNumber("123a"));
        assertFalse("Space in string", NumberUtils.isNumber("12 3"));
        assertFalse("Special characters", NumberUtils.isNumber("123!"));

        // Testing the branch: (i < sz + 1 && allowSigns && !foundDigit)
        // This covers cases where the string ends in a sign after an 'E'
        assertFalse("Ends with plus after E", NumberUtils.isNumber("123e+"));
        assertFalse("Ends with minus after E", NumberUtils.isNumber("123e-"));
    }
}
